import 'package:dio/dio.dart';
import '../../../core/network/api_exception.dart';
import './models/candidate_ranking_model.dart';

/// Reads the post-deadline rankings generated by the backend worker.
class CandidateRankingRepository {
  CandidateRankingRepository(this._dio);

  final Dio _dio;

  Future<CandidateRankingResult> loadJobRankings(String jobId) async {
    try {
      final overviewResponse =
          await _dio.get('/applications/jobs/$jobId/ai-ranking/overview');
      final overview =
          Map<String, dynamic>.from(overviewResponse.data['data'] as Map);
      final config =
          Map<String, dynamic>.from(overview['aiConfig'] as Map? ?? const {});
      final entitlements = Map<String, dynamic>.from(
          overview['entitlements'] as Map? ?? const {});
      final summaryEnabled =
          config['summary'] == true && entitlements['summary'] == true;
      final rankingEnabled =
          config['ranking'] == true && entitlements['ranking'] == true;
      if (overview['locked'] == true) {
        return CandidateRankingResult.fromApiJson({
          ...overview,
          'summaryEnabled': summaryEnabled,
          'rankingEnabled': rankingEnabled,
        });
      }
      const pageSize = 100;
      final firstResponse = await _dio.get(
        '/applications/jobs/$jobId/ai-ranking',
        queryParameters: {'page': 1, 'limit': pageSize},
      );
      final firstPage =
          Map<String, dynamic>.from(firstResponse.data['data'] as Map);
      final totalPages = (firstPage['totalPages'] as num?)?.toInt() ?? 1;
      final laterPages = totalPages <= 1
          ? <Response>[]
          : await Future.wait(List.generate(
              totalPages - 1,
              (index) => _dio.get(
                '/applications/jobs/$jobId/ai-ranking',
                queryParameters: {'page': index + 2, 'limit': pageSize},
              ),
            ));
      final allRankings = <dynamic>[
        ...(firstPage['rankings'] as List? ?? const []),
        for (final response in laterPages)
          ...((response.data['data'] as Map)['rankings'] as List? ?? const []),
      ];
      final rawRankings = allRankings.whereType<Map>().map((row) {
        final item = Map<String, dynamic>.from(row);
        final candidate =
            Map<String, dynamic>.from(item['candidate'] as Map? ?? const {});
        final profile =
            Map<String, dynamic>.from(item['profile'] as Map? ?? const {});
        final location =
            Map<String, dynamic>.from(profile['location'] as Map? ?? const {});
        return {
          ...item,
          'score': (item['match'] as Map?)?['score'] ?? 0,
          'insight': (item['match'] as Map?)?['rationale'] ?? '',
          'strengths': (item['match'] as Map?)?['highlights'] ?? const [],
          'candidate': {
            ...candidate,
            'id': candidate['_id']?.toString() ?? '',
            'name':
                '${candidate['firstName'] ?? ''} ${candidate['lastName'] ?? ''}'
                    .trim(),
            'avatarUrl': candidate['profileImage'],
          },
          'experienceYears': profile['yearsOfExperience'],
          'previousCompanies': profile['recentCompanies'] ?? const [],
          'location': [location['city'], location['countryName']]
              .whereType<String>()
              .where((part) => part.isNotEmpty)
              .join(', '),
        };
      }).toList();
      return CandidateRankingResult.fromApiJson({
        'totalRanked': firstPage['total'] ?? 0,
        'topTierCount': overview['topTierMatches'] ?? 0,
        'avgMatchScore': overview['averageMatchScore'] ?? 0,
        'summaryEnabled': summaryEnabled,
        'rankingEnabled': rankingEnabled,
        'entries': rawRankings,
      });
    } on DioException catch (e) {
      throw ApiException.fromDioError(e);
    }
  }
}
